/**
 * Password reset confirmations are read on a page before sign-in, so they are written in the
 * language of that page (Accept-Language). The router is mounted on a bare app with the same
 * locale and error middleware as main.ts; the service is mocked.
 *
 * Value: protects=forgot/reset-password 200 messages are in the page language, English by
 * default; fails_when=t(req.locale, ...) in auth/routes.ts reverts to a literal or a fixed
 * locale; why_new=main.test.ts covers only the forgot-password validation error; seam=none
 * Generated by /ship test coverage audit (pass 2).
 */
process.env.JWT_SECRET = 'test-secret';

import express from 'express';
import request from 'supertest';

jest.mock('../../shared/db.js', () => ({ prisma: {} }));
const mockForgotPassword = jest.fn();
const mockResetPassword = jest.fn();
jest.mock('./service.js', () => ({
  forgotPassword: (...args: unknown[]) => mockForgotPassword(...args),
  resetPassword: (...args: unknown[]) => mockResetPassword(...args),
}));

// Required, not imported: the auth middleware reads JWT_SECRET when it loads
const authRoutes = (require('./routes') as typeof import('./routes')).default;
const { resolveLocale } = require('../../shared/middleware/locale') as typeof import('../../shared/middleware/locale');
const { errorHandler } = require('../../shared/middleware/error-handler') as typeof import('../../shared/middleware/error-handler');

const app = express();
app.use(resolveLocale);
app.use(express.json());
app.use('/auth', authRoutes);
app.use(errorHandler);

describe('password reset confirmations in the language of the page', () => {
  beforeEach(() => {
    mockForgotPassword.mockReset().mockResolvedValue(undefined);
    mockResetPassword.mockReset().mockResolvedValue(undefined);
  });

  it('confirms a reset request in French for a French page', async () => {
    const res = await request(app)
      .post('/auth/forgot-password')
      .set('Accept-Language', 'fr-CA,fr;q=0.9')
      .send({ email: 'a@b.co' });

    expect(res.status).toBe(200);
    expect(res.body).toEqual({
      data: { message: 'Si un compte existe, un courriel de réinitialisation a été envoyé.' },
    });
    expect(mockForgotPassword).toHaveBeenCalledWith('a@b.co');
  });

  it('confirms a reset request in English when the page names no supported language', async () => {
    const res = await request(app).post('/auth/forgot-password').set('Accept-Language', 'es').send({ email: 'a@b.co' });

    expect(res.body.data.message).toBe('If an account exists, a reset email has been sent.');
  });

  it('confirms a completed reset in French for a French page', async () => {
    const res = await request(app)
      .post('/auth/reset-password')
      .set('Accept-Language', 'fr')
      .send({ token: 'tok', password: 'password123' });

    expect(res.status).toBe(200);
    expect(res.body).toEqual({ data: { message: 'Le mot de passe a été réinitialisé.' } });
    expect(mockResetPassword).toHaveBeenCalledWith('tok', 'password123');
  });

  it('confirms a completed reset in English without a language header', async () => {
    const res = await request(app).post('/auth/reset-password').send({ token: 'tok', password: 'password123' });

    expect(res.body.data.message).toBe('Password has been reset.');
  });
});
